        Vec3d const beta{u.x / gamma, u.y / gamma, u.z / gamma};

        double const r2 = R.x * R.x + R.y * R.y + R.z * R.z;
        double const rb = R.x * beta.x + R.y * beta.y + R.z * beta.z;
        double const D = r2 * invG2 + rb * rb;
